import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  asChild?: boolean
  /**
   * The action is in flight. Disables the control, reports aria-busy, and
   * swaps in a spinner while preserving the button's width, so the layout
   * does not jump when the work starts.
   *
   * Ignored for asChild, where the single child owns its own content.
   */
  pending?: boolean
  size?: "compact" | "default" | "icon"
  variant?: "default" | "secondary" | "outline" | "ghost" | "destructive" | "link"
}

// Press treatment is per-variant on purpose: a neutral surface darkens to the
// pressed role, a solid surface has no deeper solid role to move to. Every
// variant keeps a non-motion signal, because --motion-press-scale collapses to
// 1 under prefers-reduced-motion and colour does not.
const buttonVariants = {
  default: "bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)] active:bg-[var(--primary-hover)] active:opacity-90",
  secondary: "bg-[var(--secondary)] text-[var(--secondary-foreground)] hover:bg-[var(--interactive-hover)] active:bg-[var(--interactive-pressed)]",
  outline: "border border-[var(--border)] bg-[var(--background)] text-[var(--foreground)] hover:bg-[var(--interactive-hover)] active:bg-[var(--interactive-pressed)]",
  ghost: "text-[var(--foreground)] hover:bg-[var(--interactive-hover)] active:bg-[var(--interactive-pressed)]",
  destructive: "bg-[var(--destructive)] text-[var(--destructive-foreground)] hover:opacity-90 active:opacity-80",
  link: "h-auto min-h-[var(--touch-target-min)] px-1 text-[var(--foreground)] underline-offset-4 hover:underline active:opacity-80",
} as const

const buttonSizes = {
  compact: "h-[var(--control-height-compact)] max-md:min-h-[var(--touch-target-min)] pointer-coarse:min-h-[var(--touch-target-min)] px-3 text-sm",
  default: "h-[var(--control-height)] min-h-[var(--touch-target-min)] px-4 py-2",
  icon: "size-[var(--touch-target-min)] p-0",
} as const

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ asChild = false, children, className, disabled, pending = false, size = "default", variant = "default", ...props }, ref) => {
    const Comp = asChild ? Slot : "button"
    const busy = pending && !asChild
    return (
      <Comp
        ref={ref}
        aria-busy={pending || undefined}
        disabled={asChild ? undefined : disabled || pending}
        className={cn(
          "relative inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-[var(--radius)] font-medium transition-[transform,background-color,color,opacity] duration-[var(--motion-duration-instant)] ease-[var(--motion-easing-standard)] active:scale-[var(--motion-press-scale)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--interactive-focus)] focus-visible:ring-offset-2 disabled:pointer-events-none",
          // A pending button keeps its own colours. Greying it out reads as
          // "broken", which is the opposite of what it is doing.
          busy ? "active:scale-100" : "disabled:bg-[var(--interactive-disabled)] disabled:text-[var(--interactive-disabled-foreground)]",
          buttonVariants[variant],
          buttonSizes[size],
          className,
        )}
        {...props}
      >
        {busy ? (
          <>
            <span aria-hidden="true" className="pointer-events-none absolute inset-0 flex items-center justify-center">
              <Spinner />
            </span>
            {/* Kept in the layout, hidden from view: this is what preserves the width. */}
            <span className="invisible inline-flex items-center gap-2">{children}</span>
          </>
        ) : (
          children
        )}
      </Comp>
    )
  },
)
Button.displayName = "Button"

export { Button, buttonSizes, buttonVariants }

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"

export type UDesignTone = "neutral" | "info" | "success" | "warning" | "danger" | "progress" | "brand"
export type BadgeVariant = "subtle" | "solid" | "outline"

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  asChild?: boolean
  tone?: UDesignTone
  variant?: BadgeVariant
}

const toneClasses: Record<UDesignTone, Record<BadgeVariant, string>> = {
  neutral: {
    subtle: "border-[var(--tone-neutral-border)] bg-[var(--tone-neutral-surface)] text-[var(--tone-neutral-foreground)]",
    solid: "border-transparent bg-[var(--tone-neutral-solid)] text-[var(--tone-neutral-solid-foreground)]",
    outline: "border-[var(--tone-neutral-border)] bg-transparent text-[var(--tone-neutral-foreground)]",
  },
  info: {
    subtle: "border-[var(--tone-info-border)] bg-[var(--tone-info-surface)] text-[var(--tone-info-foreground)]",
    solid: "border-transparent bg-[var(--tone-info-solid)] text-[var(--tone-info-solid-foreground)]",
    outline: "border-[var(--tone-info-border)] bg-transparent text-[var(--tone-info-foreground)]",
  },
  success: {
    subtle: "border-[var(--tone-success-border)] bg-[var(--tone-success-surface)] text-[var(--tone-success-foreground)]",
    solid: "border-transparent bg-[var(--tone-success-solid)] text-[var(--tone-success-solid-foreground)]",
    outline: "border-[var(--tone-success-border)] bg-transparent text-[var(--tone-success-foreground)]",
  },
  warning: {
    subtle: "border-[var(--tone-warning-border)] bg-[var(--tone-warning-surface)] text-[var(--tone-warning-foreground)]",
    solid: "border-transparent bg-[var(--tone-warning-solid)] text-[var(--tone-warning-solid-foreground)]",
    outline: "border-[var(--tone-warning-border)] bg-transparent text-[var(--tone-warning-foreground)]",
  },
  danger: {
    subtle: "border-[var(--tone-danger-border)] bg-[var(--tone-danger-surface)] text-[var(--tone-danger-foreground)]",
    solid: "border-transparent bg-[var(--tone-danger-solid)] text-[var(--tone-danger-solid-foreground)]",
    outline: "border-[var(--tone-danger-border)] bg-transparent text-[var(--tone-danger-foreground)]",
  },
  progress: {
    subtle: "border-[var(--tone-progress-border)] bg-[var(--tone-progress-surface)] text-[var(--tone-progress-foreground)]",
    solid: "border-transparent bg-[var(--tone-progress-solid)] text-[var(--tone-progress-solid-foreground)]",
    outline: "border-[var(--tone-progress-border)] bg-transparent text-[var(--tone-progress-foreground)]",
  },
  brand: {
    subtle: "border-[var(--tone-brand-border)] bg-[var(--tone-brand-surface)] text-[var(--tone-brand-foreground)]",
    solid: "border-transparent bg-[var(--tone-brand-solid)] text-[var(--tone-brand-solid-foreground)]",
    outline: "border-[var(--tone-brand-border)] bg-transparent text-[var(--tone-brand-foreground)]",
  },
}

const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  ({ asChild = false, className, tone = "neutral", variant = "subtle", ...props }, ref) => {
    const Comp = asChild ? Slot : "span"
    return (
      <Comp
        ref={ref}
        className={cn(
          "inline-flex min-h-6 items-center gap-1 whitespace-nowrap rounded-full border px-2.5 py-0.5 text-xs font-semibold leading-none [font-variant-numeric:var(--font-numeric-variant)]",
          toneClasses[tone][variant],
          className,
        )}
        {...props}
      />
    )
  },
)
Badge.displayName = "Badge"

export { Badge, toneClasses }

